import React from 'react';
import { Post } from './data/posts';
import AnimatedText from './components/AnimatedText';
import AnimatedList from './components/AnimatedList';
import { truncateAtWordBoundary } from './utils/textUtils';

interface PostListProps {
  posts: Post[];
}

const PostList: React.FC<PostListProps> = ({ posts }) => {

  const renderPost = (post: Post) => {
    switch (post.type) {
      case 'essay':
        return (
          <div className="essay-post">
            <h3><AnimatedText text={post.title} preserveWhitespace={true} /></h3>
            <p><AnimatedText 
                text={truncateAtWordBoundary(post.content, 100)} 
                preserveWhitespace={true} 
              /></p>
          </div>
        );
      case 'movie':
        return (
          <div className="movie-post">
            <h3><AnimatedText text={post.title} preserveWhitespace={true} /></h3>
            <iframe src={post.videoUrl} title={post.title} width="300" height="200" />
            <p><AnimatedText 
                text={truncateAtWordBoundary(post.description, 150)} 
                preserveWhitespace={true} 
              /></p>
          </div>
        );
      case 'image':
        return (
          <div className="image-post">
            <h3><AnimatedText text={post.title} preserveWhitespace={true} /></h3>
            <img src={post.imageUrl} alt={post.title} style={{ maxWidth: '300px' }} />
            <p><AnimatedText 
                text={truncateAtWordBoundary(post.description, 150)} 
                preserveWhitespace={true} 
              /></p>
          </div>
        );
      case 'carousel':
        return (
          <div className="carousel-post">
            <h3><AnimatedText text={post.title} preserveWhitespace={true} /></h3>
            <div className="carousel">
              {post.images.map((image, index) => (
                <div key={index}>
                  <img src={image.url} alt={image.caption} style={{ maxWidth: '300px' }} />
                  <p><AnimatedText 
                      text={truncateAtWordBoundary(image.caption, 100)} 
                      preserveWhitespace={true} 
                    /></p>
                </div>
              ))}
            </div>
          </div>
        );
    }
  };

  return (
    <AnimatedList 
      className="post-list" 
      staggerDelay={0.05}
      priority={5} // Medium priority, after page transitions
    >
      {posts.map((post, index) => (
        <li key={post.id} className="category-item post-item">
          {renderPost(post)}
          <span className="count">
            <AnimatedText 
              text={`${post.votes} votes`} 
              preserveWhitespace={true}
              priority={3} // Lower priority
            />
          </span>
        </li>
      ))}
    </AnimatedList>
  );
};

export default PostList;
